import { test } from "node:test"
import assert from "node:assert/strict"
import { readFileSync } from "node:fs"
import { uncompressInt64, uncompressUint32, uncompressUint64 } from "../src/bsup/intcomp.ts"
import { intcomp64, intcompUint32 } from "./helpers/encode.ts"

interface Case {
  name: string
  kind: "uint32" | "uint64" | "int64"
  values: string[] | null
  hex: string
}

function fromHex(h: string): Uint8Array {
  const out = new Uint8Array(h.length / 2)
  for (let k = 0; k < out.length; k++) out[k] = parseInt(h.slice(2 * k, 2 * k + 2), 16)
  return out
}

// Fixtures generated by the Go codec (scripts/intcomp).
const cases: Case[] = JSON.parse(readFileSync(new URL("./intcomp-fixtures.json", import.meta.url), "utf8"))

for (const c of cases) {
  test(`intcomp ${c.name}`, () => {
    const bytes = fromHex(c.hex)
    const want = c.values ?? []
    let got: string[]
    switch (c.kind) {
      case "uint32":
        got = Array.from(uncompressUint32(bytes, want.length), String)
        break
      case "uint64":
        got = Array.from(uncompressUint64(bytes, want.length), String)
        break
      case "int64":
        got = Array.from(uncompressInt64(bytes, want.length), String)
        break
    }
    assert.deepEqual(got, want)
  })
}

test("intcomp test encoders round trip", () => {
  const u32 = [0, 1, 300, 5, 0xffffffff, 7]
  assert.deepEqual(Array.from(uncompressUint32(intcompUint32(u32))), u32)
  const i64 = [0n, -1n, 1n << 62n, -(1n << 63n), (1n << 63n) - 1n, 42n]
  assert.deepEqual(Array.from(uncompressInt64(intcomp64(i64))), i64)
})

test("intcomp count mismatch throws", () => {
  assert.throws(() => uncompressUint32(intcompUint32([1, 2, 3]), 2))
})
